input.command:
node -e '
const T_E=365.25, T_M=686.98, A_M=1.524;
const A_T=(1+A_M)/2, E_T=(A_M-1)/(A_M+1);
const TRANSFER=(T_E/2)*Math.pow(A_T,1.5);
const PHASE=180-360*TRANSFER/T_M;
const relRate=360*(1/T_M-1/T_E);
const reqDelta=360*TRANSFER/T_E-180;
let d1=(reqDelta-PHASE)/relRate; const synodic=360/(-relRate);
while(d1<=TRANSFER) d1+=synodic;
const STAY=d1-TRANSFER, TOTAL=2*TRANSFER+STAY;
console.log("TRANSFER",TRANSFER.toFixed(3));
console.log("PHASE",PHASE.toFixed(3));
console.log("d1",d1.toFixed(3));
console.log("STAY",STAY.toFixed(3));
console.log("TOTAL",TOTAL.toFixed(3));
// verify arrival at Mars
const angM=d=>(PHASE+360*d/T_M)%360;
const angE=d=>(0+360*d/T_E)%360;
console.log("Mars@TRANSFER",angM(TRANSFER).toFixed(3),"ship@",(0+180)%360);
console.log("Earth@TOTAL",angE(TOTAL).toFixed(3),"ship@",(angM(d1)+180)%360);
'

